/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_i2c.c
 *
 * D13x DesignWare I2C Master Driver (NuttX)
 * 寄存器来源: luban-lite hal_i2c.h + D13x User Manual §10
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/mutex.h>
#include <nuttx/i2c/i2c_master.h>
#include <debug.h>
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* DesignWare I2C 寄存器偏移 (来源: luban-lite hal_i2c.h) */

#define DW_I2C_CTL               0x00
#define DW_I2C_TAR               0x04
#define DW_I2C_SAR               0x08
#define DW_I2C_DATA_CMD          0x10
#define DW_I2C_SS_SCL_HCNT       0x20
#define DW_I2C_SS_SCL_LCNT       0x24
#define DW_I2C_FS_SCL_HCNT       0x28
#define DW_I2C_FS_SCL_LCNT       0x2C
#define DW_I2C_SDA_HOLD          0x30
#define DW_I2C_INTR_MASK         0x38
#define DW_I2C_INTR_CLR          0x3C
#define DW_I2C_INTR_RAW_STAT     0x40
#define DW_I2C_ENABLE            0x48
#define DW_I2C_ENABLE_STATUS     0x4C
#define DW_I2C_STATUS            0x50
#define DW_I2C_TX_ABRT_SOURCE    0x54
#define DW_I2C_TXFLR             0x98
#define DW_I2C_RXFLR             0x9C

/* CTL 位域 */

#define DW_I2C_CTL_MASTER        (0x0 << 0)
#define DW_I2C_CTL_SPEED_SS      (0x1 << 4)
#define DW_I2C_CTL_SPEED_FS      (0x2 << 4)
#define DW_I2C_CTL_RESTART_EN    (1 << 6)

/* DATA_CMD 位域 */

#define DW_I2C_DATA_CMD_READ     (1 << 8)
#define DW_I2C_DATA_CMD_STOP     (1 << 9)
#define DW_I2C_DATA_CMD_RESTART  (1 << 10)

/* INTR 位域 */

#define DW_I2C_INTR_TX_EMPTY     (1 << 4)
#define DW_I2C_INTR_TX_ABRT      (1 << 6)
#define DW_I2C_INTR_RX_FULL      (1 << 2)
#define DW_I2C_INTR_STOP_DET     (1 << 9)

/* ENABLE 位域 */

#define DW_I2C_ENABLE_BIT        (1 << 0)

/* STATUS 位域 */

#define DW_I2C_STATUS_ACTIVITY   (1 << 0)

/* FIFO 深度 */

#define DW_I2C_FIFO_DEPTH        8

/* 超时 (微秒) */

#define DW_I2C_TIMEOUT_US        100000

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct d13x_i2c_priv_s
{
  struct i2c_master_s  dev;     /* NuttX I2C master 接口 */
  uint32_t             base;    /* I2C 控制器基地址 */
  uint8_t              irq;     /* 中断号 */
  mutex_t              lock;    /* 互斥锁 */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

#ifdef CONFIG_D13X_I2C0
static struct d13x_i2c_priv_s g_i2c0_priv =
{
  .base = D13X_I2C0_BASE,
  .irq  = 84,
};
#endif

#ifdef CONFIG_D13X_I2C1
static struct d13x_i2c_priv_s g_i2c1_priv =
{
  .base = D13X_I2C1_BASE,
  .irq  = 85,
};
#endif

#ifdef CONFIG_D13X_I2C2
static struct d13x_i2c_priv_s g_i2c2_priv =
{
  .base = D13X_I2C2_BASE,
  .irq  = 86,
};
#endif

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void dw_i2c_write(struct d13x_i2c_priv_s *priv,
                                uint32_t offset, uint32_t value)
{
  putreg32(value, priv->base + offset);
}

static inline uint32_t dw_i2c_read(struct d13x_i2c_priv_s *priv,
                                   uint32_t offset)
{
  return getreg32(priv->base + offset);
}

static void dw_i2c_enable(struct d13x_i2c_priv_s *priv)
{
  uint32_t reg = dw_i2c_read(priv, DW_I2C_ENABLE);
  reg |= DW_I2C_ENABLE_BIT;
  dw_i2c_write(priv, DW_I2C_ENABLE, reg);
}

static void dw_i2c_disable(struct d13x_i2c_priv_s *priv)
{
  uint32_t reg = dw_i2c_read(priv, DW_I2C_ENABLE);
  reg &= ~DW_I2C_ENABLE_BIT;
  dw_i2c_write(priv, DW_I2C_ENABLE, reg);
}

static int dw_i2c_wait_bus_idle(struct d13x_i2c_priv_s *priv)
{
  uint32_t timeout = DW_I2C_TIMEOUT_US;

  while (dw_i2c_read(priv, DW_I2C_STATUS) & DW_I2C_STATUS_ACTIVITY)
    {
      if (--timeout == 0)
        {
          return -ETIMEDOUT;
        }

      up_udelay(1);
    }

  return OK;
}

static int dw_i2c_send_addr(struct d13x_i2c_priv_s *priv,
                            uint16_t addr, bool restart)
{
  uint32_t cmd = addr & 0x7FF;

  if (restart)
    {
      cmd |= DW_I2C_DATA_CMD_RESTART;
    }

  dw_i2c_write(priv, DW_I2C_DATA_CMD, cmd);
  return OK;
}

static int dw_i2c_xfer_write(struct d13x_i2c_priv_s *priv,
                             struct i2c_msg_s *msg)
{
  uint32_t timeout;
  int i;

  /* 设置目标地址 */

  dw_i2c_write(priv, DW_I2C_TAR, msg->addr);

  /* 发送写命令 */

  for (i = 0; i < msg->length; i++)
    {
      uint32_t cmd = msg->buffer[i];

      /* 最后一个字节时设置 STOP 位 */

      if (i == msg->length - 1)
        {
          cmd |= DW_I2C_DATA_CMD_STOP;
        }

      /* 等待 TX FIFO 有空间 */

      timeout = DW_I2C_TIMEOUT_US;
      while (dw_i2c_read(priv, DW_I2C_TXFLR) >= DW_I2C_FIFO_DEPTH)
        {
          if (dw_i2c_read(priv, DW_I2C_INTR_RAW_STAT) & DW_I2C_INTR_TX_ABRT)
            {
              dw_i2c_read(priv, DW_I2C_INTR_CLR);
              return -EIO;
            }

          if (--timeout == 0)
            {
              return -ETIMEDOUT;
            }

          up_udelay(1);
        }

      dw_i2c_write(priv, DW_I2C_DATA_CMD, cmd);
    }

  /* 等待传输完成 */

  timeout = DW_I2C_TIMEOUT_US;
  while (!(dw_i2c_read(priv, DW_I2C_INTR_RAW_STAT) & DW_I2C_INTR_STOP_DET))
    {
      if (dw_i2c_read(priv, DW_I2C_INTR_RAW_STAT) & DW_I2C_INTR_TX_ABRT)
        {
          dw_i2c_read(priv, DW_I2C_INTR_CLR);
          return -EIO;
        }

      if (--timeout == 0)
        {
          return -ETIMEDOUT;
        }

      up_udelay(1);
    }

  /* 清除中断标志 */

  dw_i2c_read(priv, DW_I2C_INTR_CLR);

  return msg->length;
}

static int dw_i2c_xfer_read(struct d13x_i2c_priv_s *priv,
                            struct i2c_msg_s *msg)
{
  uint32_t timeout;
  int i;
  int rx_cnt = 0;

  /* 设置目标地址 */

  dw_i2c_write(priv, DW_I2C_TAR, msg->addr);

  /* 发送读命令 */

  for (i = 0; i < msg->length; i++)
    {
      uint32_t cmd = DW_I2C_DATA_CMD_READ;

      /* 最后一个字节时设置 STOP 位 */

      if (i == msg->length - 1)
        {
          cmd |= DW_I2C_DATA_CMD_STOP;
        }

      dw_i2c_write(priv, DW_I2C_DATA_CMD, cmd);
    }

  /* 读取数据 */

  for (i = 0; i < msg->length; i++)
    {
      timeout = DW_I2C_TIMEOUT_US;

      while (dw_i2c_read(priv, DW_I2C_RXFLR) == 0)
        {
          if (dw_i2c_read(priv, DW_I2C_INTR_RAW_STAT) & DW_I2C_INTR_TX_ABRT)
            {
              dw_i2c_read(priv, DW_I2C_INTR_CLR);
              return -EIO;
            }

          if (--timeout == 0)
            {
              return -ETIMEDOUT;
            }

          up_udelay(1);
        }

      msg->buffer[i] = (uint8_t)(dw_i2c_read(priv, DW_I2C_DATA_CMD) & 0xFF);
      rx_cnt++;
    }

  /* 等待 STOP 检测 */

  timeout = DW_I2C_TIMEOUT_US;
  while (!(dw_i2c_read(priv, DW_I2C_INTR_RAW_STAT) & DW_I2C_INTR_STOP_DET))
    {
      if (--timeout == 0)
        {
          break;
        }

      up_udelay(1);
    }

  /* 清除中断标志 */

  dw_i2c_read(priv, DW_I2C_INTR_CLR);

  return rx_cnt;
}

/****************************************************************************
 * Name: d13x_i2c_transfer
 *
 * Description:
 *   执行 I2C 传输
 *
 ****************************************************************************/

static int d13x_i2c_transfer(struct i2c_master_s *dev,
                             struct i2c_msg_s *msgs, int count)
{
  struct d13x_i2c_priv_s *priv = (struct d13x_i2c_priv_s *)dev;
  int ret = 0;
  int i;

  nxmutex_lock(&priv->lock);

  for (i = 0; i < count; i++)
    {
      struct i2c_msg_s *msg = &msgs[i];

      if (msg->flags & I2C_M_READ)
        {
          ret = dw_i2c_xfer_read(priv, msg);
        }
      else
        {
          ret = dw_i2c_xfer_write(priv, msg);
        }

      if (ret < 0)
        {
          ierr("I2C 传输失败: %d\n", ret);
          break;
        }
    }

  nxmutex_unlock(&priv->lock);
  return (ret < 0) ? ret : count;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_i2c_initialize
 *
 * Description:
 *   初始化指定的 I2C 总线
 *
 ****************************************************************************/

int d13x_i2c_initialize(int bus)
{
  struct d13x_i2c_priv_s *priv;
  uint32_t reg;

  switch (bus)
    {
#ifdef CONFIG_D13X_I2C0
      case 0:
        priv = &g_i2c0_priv;
        break;
#endif
#ifdef CONFIG_D13X_I2C1
      case 1:
        priv = &g_i2c1_priv;
        break;
#endif
#ifdef CONFIG_D13X_I2C2
      case 2:
        priv = &g_i2c2_priv;
        break;
#endif
      default:
        return -EINVAL;
    }

  /* 使能 I2C 模块时钟 */

  reg = getreg32(D13X_CMU_BASE + 0x844 + bus * 4);
  reg |= (1 << 13) | (1 << 12) | (1 << 8);
  putreg32(reg, D13X_CMU_BASE + 0x844 + bus * 4);

  /* 禁用 I2C 以配置 */

  dw_i2c_disable(priv);

  /* 配置为主模式, Fast Mode (400kHz), 重启使能 */

  reg = DW_I2C_CTL_MASTER | DW_I2C_CTL_SPEED_FS | DW_I2C_CTL_RESTART_EN;
  dw_i2c_write(priv, DW_I2C_CTL, reg);

  /* 配置 SCL 时序 (400kHz @ 24MHz APB0)
   * FS_SCL_HCNT = 24000000 / (2 * 400000) - 8 = 22
   * FS_SCL_LCNT = 24000000 / (2 * 400000) - 1 = 29
   */

  dw_i2c_write(priv, DW_I2C_FS_SCL_HCNT, 22);
  dw_i2c_write(priv, DW_I2C_FS_SCL_LCNT, 29);

  /* 设置 SDA 保持时间 */

  dw_i2c_write(priv, DW_I2C_SDA_HOLD, 12);

  /* 设置 TX/RX FIFO 阈值 */

  dw_i2c_write(priv, DW_I2C_INTR_CLR, 0xFFFF);
  dw_i2c_write(priv, DW_I2C_INTR_MASK, 0);

  /* 使能 I2C */

  dw_i2c_enable(priv);

  /* 初始化互斥锁 */

  nxmutex_init(&priv->lock);

  iinfo("I2C%d 初始化完成, 基地址=0x%08X\n", bus, priv->base);

  return OK;
}

/****************************************************************************
 * Name: d13x_i2c_get_bus
 *
 * Description:
 *   获取指定 I2C 总线的 master 接口
 *
 ****************************************************************************/

struct i2c_master_s *d13x_i2c_get_bus(int bus)
{
  switch (bus)
    {
#ifdef CONFIG_D13X_I2C0
      case 0:
        return &g_i2c0_priv.dev;
#endif
#ifdef CONFIG_D13X_I2C1
      case 1:
        return &g_i2c1_priv.dev;
#endif
#ifdef CONFIG_D13X_I2C2
      case 2:
        return &g_i2c2_priv.dev;
#endif
      default:
        return NULL;
    }
}

/****************************************************************************
 * vendor/artinchip/boards/d13x-hengshan-pi/src/artinchip_touch.c
 *
 * D13x Hengshan Pi GT911 触摸板级回调
 * 引脚配置来源: luban-lite Kconfig + D13x Pinmux Manual
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/input/touchscreen.h>
#include <nuttx/input/gt9xx.h>
