/* GT911 I2C 地址 (来源: GT911 datasheet, INT=LOW 时为 0x5D) */

#define GT911_I2C_ADDR          0x5D

/* GT911 I2C 总线号 (来源: luban-lite Kconfig) */

#define GT911_I2C_BUS           0

/* GT911 触摸复位引脚 (来源: luban-lite Kconfig AIC_TOUCH_PANEL_GT911_RST_PIN) */

#define GT911_RST_PIN           0   /* PA.0 */

/* GT911 触摸中断引脚 (来源: luban-lite Kconfig AIC_TOUCH_PANEL_GT911_INT_PIN) */

#define GT911_INT_PIN           2   /* PA.2 */

/* GPIO 寄存器 (来源: D13x User Manual §10.3) */

#define D13X_GPIO_PIE(i)       (D13X_GPIO_BASE + 0x00 + (i) * 4)  /* 输入使能 */
#define D13X_GPIO_POE(i)       (D13X_GPIO_BASE + 0x20 + (i) * 4)  /* 输出使能 */
#define D13X_GPIO_PDS(i)       (D13X_GPIO_BASE + 0x30 + (i) * 4)  /* 数据寄存器 */
#define D13X_GPIO_PDE(i)       (D13X_GPIO_BASE + 0x60 + (i) * 4)  /* 下拉使能 */
#define D13X_GPIO_PUE(i)       (D13X_GPIO_BASE + 0x70 + (i) * 4)  /* 上拉使能 */
#define D13X_GPIO_PCEN(i)      (D13X_GPIO_BASE + 0xA0 + (i) * 4)  /* 去抖使能 */

/* GPIO 组基地址: PA=0, PB=1, PC=2, PD=3, PE=4, PF=5 */

#define GPIO_GROUP(pin)         ((pin) >> 4)
#define GPIO_PIN(pin)           ((pin) & 0x0F)

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void gpio_set_output(int pin)
{
  uint32_t group = GPIO_GROUP(pin);
  uint32_t bit = GPIO_PIN(pin);
  uint32_t reg;

  /* 输出使能 */

  reg = getreg32(D13X_GPIO_POE(group));
  reg |= (1 << bit);
  putreg32(reg, D13X_GPIO_POE(group));

  /* 禁用输入 */

  reg = getreg32(D13X_GPIO_PIE(group));
  reg &= ~(1 << bit);
  putreg32(reg, D13X_GPIO_PIE(group));
}

static inline void gpio_set_input(int pin)
{
  uint32_t group = GPIO_GROUP(pin);
  uint32_t bit = GPIO_PIN(pin);
  uint32_t reg;

  /* 输入使能 */

  reg = getreg32(D13X_GPIO_PIE(group));
  reg |= (1 << bit);
  putreg32(reg, D13X_GPIO_PIE(group));

  /* 禁用输出 */

  reg = getreg32(D13X_GPIO_POE(group));
  reg &= ~(1 << bit);
  putreg32(reg, D13X_GPIO_POE(group));
}

static inline void gpio_write(int pin, bool value)
{
  uint32_t group = GPIO_GROUP(pin);
  uint32_t bit = GPIO_PIN(pin);
  uint32_t reg;

  reg = getreg32(D13X_GPIO_PDS(group));
  if (value)
    {
      reg |= (1 << bit);
    }
  else
    {
      reg &= ~(1 << bit);
    }

  putreg32(reg, D13X_GPIO_PDS(group));
}

/****************************************************************************
 * GT911 复位时序 (来源: luban-lite gt911.c rt_hw_gt911_init)
 *
 * 1. RST=LOW, 等待 10ms
 * 2. INT=LOW
 * 3. 等待 2ms
 * 4. RST=HIGH
 * 5. 等待 5ms
 * 6. RST 切换为输入
 * 7. INT=LOW, 等待 50ms
 * 8. INT 切换为输入
 ****************************************************************************/

static void gt911_hw_reset(void)
{
  /* 1. RST=LOW */

  gpio_set_output(GT911_RST_PIN);
  gpio_write(GT911_RST_PIN, false);
  up_mdelay(10);

  /* 2-3. INT=LOW, 等待 2ms */

  gpio_set_output(GT911_INT_PIN);
  gpio_write(GT911_INT_PIN, false);
  up_mdelay(2);

  /* 4-5. RST=HIGH, 等待 5ms */

  gpio_write(GT911_RST_PIN, true);
  up_mdelay(5);

  /* 6. RST 切换为输入 */

  gpio_set_input(GT911_RST_PIN);

  /* 7-8. INT=LOW, 等待 50ms 后切换为输入 */

  gpio_write(GT911_INT_PIN, false);
  up_mdelay(50);
  gpio_set_input(GT911_INT_PIN);
}

/****************************************************************************
 * GT911 板级回调: IRQ 附加
 ****************************************************************************/

static int gt911_irq_attach(const struct gt9xx_board_s *state,
                            xcpt_t isr, FAR void *arg)
{
  (void)state;
  (void)isr;
  (void)arg;

  /* GT911 使用 GPIO 中断, 此处暂不实现硬件中断
   * 后续可通过 up_disable_irq/enable_irq 实现
   */

  return OK;
}

/****************************************************************************
 * GT911 板级回调: IRQ 使能/禁用
 ****************************************************************************/

static void gt911_irq_enable(const struct gt9xx_board_s *state, bool enable)
{
  (void)state;

  if (enable)
    {
      /* 使能 GPIO 中断 */
    }
  else
    {
      /* 禁用 GPIO 中断 */
    }
}

/****************************************************************************
 * GT911 板级回调: 电源控制
 ****************************************************************************/

static int gt911_set_power(const struct gt9xx_board_s *state, bool on)
{
  (void)state;

  if (on)
    {
      /* 使能电源 (如有外部电源控制引脚) */
      gpio_set_output(GT911_RST_PIN);
      gpio_write(GT911_RST_PIN, true);
      up_mdelay(20);
    }
  else
    {
      /* 关闭电源 */
      gpio_set_output(GT911_RST_PIN);
      gpio_write(GT911_RST_PIN, false);
    }

  return OK;
}

/****************************************************************************
 * GT911 板级回调表
 ****************************************************************************/

static const struct gt9xx_board_s g_gt911_board =
{
  .irq_attach = gt911_irq_attach,
  .irq_enable = gt911_irq_enable,
  .set_power  = gt911_set_power,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_touch_gt911_initialize
 *
 * Description:
 *   初始化 GT911 触摸控制器
 *
 ****************************************************************************/

int d13x_touch_gt911_initialize(void)
{
  struct i2c_master_s *i2c;
  int ret;

  /* 硬件复位 GT911 */

  gt911_hw_reset();

  /* 获取 I2C 总线 */

  i2c = d13x_i2c_get_bus(GT911_I2C_BUS);
  if (i2c == NULL)
    {
      ierr("无法获取 I2C%d 总线\n", GT911_I2C_BUS);
      return -ENODEV;
    }

  /* 注册 GT911 驱动 */

  ret = gt9xx_register("/dev/input0", i2c, GT911_I2C_ADDR, &g_gt911_board);
  if (ret < 0)
    {
      ierr("GT911 注册失败: %d\n", ret);
      return ret;
    }

  iinfo("GT911 触摸控制器初始化完成\n");
  return OK;
}

