/****************************************************************************
 * GT911 I2C 辅助函数
 ****************************************************************************/

static int gt911_i2c_write_reg(struct i2c_master_s *i2c, uint16_t reg,
                               const uint8_t *data, uint8_t len)
{
  uint8_t buf[2 + 64];  /* 寄存器地址(2字节) + 数据 */
  struct i2c_msg_s msg;
  int ret;

  if (len > 64)
    {
      return -EINVAL;
    }

  /* 构建写缓冲区: 寄存器地址(MSB first) + 数据 */

  buf[0] = (reg >> 8) & 0xff;
  buf[1] = reg & 0xff;
  memcpy(&buf[2], data, len);

  msg.frequency = 400000;
  msg.addr = GT911_I2C_ADDR;
  msg.flags = 0;
  msg.buffer = buf;
  msg.length = len + 2;

  ret = I2C_TRANSFER(i2c, &msg, 1);
  return (ret == 1) ? OK : -EIO;
}

/****************************************************************************
 * gt911_write_config - 写入GT911配置表
 *
 * 描述:
 *   向GT911写入配置参数（分辨率、触摸点数、中断模式等）
 *   来源: luban-lite gt911.c gt911_control()
 *
 ****************************************************************************/

static int gt911_write_config(struct i2c_master_s *i2c)
{
  uint8_t buf[2 + sizeof(gt911_config_table) + 1];
  uint8_t checksum = 0;
  int i;
  int ret;

  /* 构建写缓冲区: 寄存器地址(0x8047) + 配置数据 + 校验和 */

  buf[0] = 0x80;  /* 配置寄存器地址高字节 */
  buf[1] = 0x47;  /* 配置寄存器地址低字节 */
  memcpy(&buf[2], gt911_config_table, sizeof(gt911_config_table));

  /* 计算校验和: 所有配置字节求和, 取反加1 */

  for (i = 0; i < sizeof(gt911_config_table); i++)
    {
      checksum += gt911_config_table[i];
    }

  checksum = (~checksum) + 1;
  buf[2 + sizeof(gt911_config_table)] = checksum;

  /* 写入配置 */

  struct i2c_msg_s msg;
  msg.frequency = 400000;
  msg.addr = GT911_I2C_ADDR;
  msg.flags = 0;
  msg.buffer = buf;
  msg.length = sizeof(buf);

  ret = I2C_TRANSFER(i2c, &msg, 1);
  if (ret != 1)
    {
      ierr("GT911 配置写入失败\n");
      return -EIO;
    }

  /* 写入配置更新标志 (寄存器0x8100 = 1) */

  uint8_t update_buf[3] = { 0x81, 0x00, 0x01 };
  msg.buffer = update_buf;
  msg.length = 3;
  ret = I2C_TRANSFER(i2c, &msg, 1);
  if (ret != 1)
    {
      ierr("GT911 配置更新标志写入失败\n");
      return -EIO;
    }

  /* 等待配置生效 */

  up_mdelay(50);

  iinfo("GT911 配置写入完成\n");
  return OK;
}

int d13x_touch_gt911_initialize(void)
{
  struct i2c_master_s *i2c;
  int ret;

  /* 硬件复位 GT911 */

  gt911_hw_reset();

  /* 获取 I2C 总线 */

  i2c = d13x_i2c_get_bus(GT911_I2C_BUS);
  if (i2c == NULL)
    {
      ierr("无法获取 I2C%d 总线\n", GT911_I2C_BUS);
      return -ENODEV;
    }

  /* 写入 GT911 配置 (分辨率、触摸点数、中断模式等) */

  ret = gt911_write_config(i2c);
  if (ret < 0)
    {
      ierr("GT911 配置写入失败: %d\n", ret);
      /* 继续注册驱动, 使用默认配置 */
    }

  /* 注册 GT911 驱动 */

  ret = gt9xx_register("/dev/input0", i2c, GT911_I2C_ADDR, &g_gt911_board);
  if (ret < 0)
    {
      ierr("GT911 注册失败: %d\n", ret);
      return ret;
    }

  iinfo("GT911 触摸控制器初始化完成\n");
  return OK;
}

